html,body{margin:0;height:100%;background:#0f172a;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.wrap{height:calc(var(--appsmith-ui-height)*1px);overflow-y:auto;overflow-x:hidden;padding:18px 26px 40px;}
.top{display:flex;align-items:flex-start;gap:24px;margin-bottom:20px;}
.fld{flex:0 0 auto;}
.fld label{display:block;font-size:14px;color:#60a5fa;font-weight:600;margin-bottom:8px;}
.dateinput{background:#1e293b;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:9px 12px;font-size:14px;min-width:360px;height:40px;display:flex;align-items:center;gap:8px;cursor:pointer;}
.dateinput .ph{color:#94a3b8;} .dateinput.has .ph{color:#e2e8f0;}
.dateinput .clr{margin-left:auto;color:#94a3b8;font-size:15px;padding:0 2px;}
.dateinput .clr:hover{color:#e2e8f0;}
.pop{position:absolute;top:74px;left:0;z-index:50;background:#1e293b;border:1px solid #334155;border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.5);padding:14px;width:340px;}
.pop .nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;}
.pop .nav b{font-size:15px;color:#f1f5f9;}
.pop .nav span{cursor:pointer;color:#cbd5e1;font-size:20px;padding:2px 10px;border-radius:6px;line-height:1;}
.pop .nav span:hover{background:#334155;}
.pop .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}
.pop .grid b{text-align:center;padding:13px 0;border-radius:8px;font-size:14px;font-weight:600;color:#cbd5e1;cursor:pointer;}
.pop .grid b:hover{background:#334155;}
.pop .grid b.on{background:#2563eb;color:#fff;}
.monthnav{flex:1 1 auto;display:flex;align-items:center;justify-content:center;gap:22px;padding-top:20px;}
.monthnav .arw{cursor:pointer;color:#3b82f6;font-size:26px;line-height:1;padding:2px 8px;border-radius:6px;user-select:none;}
.monthnav .arw:hover{background:#1e293b;}
.monthnav .lbl{text-align:center;min-width:120px;}
.monthnav .lbl .m{font-size:18px;font-weight:700;color:#f1f5f9;}
.monthnav .lbl .y{font-size:16px;color:#cbd5e1;}
.totals{flex:0 0 auto;text-align:right;padding-top:16px;font-size:15px;color:#cbd5e1;line-height:1.7;}
.totals b{color:#f1f5f9;font-weight:800;margin-left:6px;}
.cal{display:grid;grid-template-columns:repeat(7,1fr);gap:14px;}
.card{border:1px solid #1e293b;border-radius:6px;overflow:hidden;background:#0b1220;display:flex;flex-direction:column;min-height:170px;}
.card .hd{background:#16233b;color:#e8eefc;font-size:13px;font-weight:600;padding:8px 10px;display:flex;align-items:center;justify-content:center;gap:8px;}
.card.out .hd{background:#334155;color:#cbd5e1;}
.card .hd svg{flex:0 0 auto;}
.card .bd{flex:1 1 auto;padding:12px 12px;display:flex;flex-direction:column;justify-content:center;gap:10px;}
.card .r{display:flex;justify-content:space-between;font-size:13px;}
.card .r .k{color:#94a3b8;} .card .r .v{color:#e2e8f0;font-weight:600;}
.card.nodata .bd{background:#0f172a;align-items:center;justify-content:center;}
.card.nodata .msg{color:#64748b;font-size:13px;text-align:center;}
.empty{padding:50px;text-align:center;color:#64748b;font-style:italic;}
::-webkit-scrollbar{width:10px;height:10px;background:#0f172a;} ::-webkit-scrollbar-thumb{background:#1e293b;border-radius:4px;border:2px solid #0f172a;}

