function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function n2(n){ var v=Number(n); if(!isFinite(v)) return "0"; return (Math.round(v*100)/100).toString(); }
var MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];
var M3=["JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"];
var DOW=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
var CAL='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>';
var selY=null, selM=null, pickerOpen=false, pickerYear=(new Date()).getFullYear(), inited=false;

function wsvg(inner){ return '<svg width="18" height="18" viewBox="0 0 24 24">'+inner+'</svg>'; }
function icon(name){
  name=String(name||"").toLowerCase();
  var s='stroke="#e8eefc" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"';
  var cloud='<path '+s+' d="M6 16h10a3.2 3.2 0 0 0 .2-6.4A4.8 4.8 0 0 0 7 8.4 3.4 3.4 0 0 0 6 16z"/>';
  if(name.indexOf("rain")>-1||name.indexOf("shower")>-1||name.indexOf("drizzle")>-1||name.indexOf("sleet")>-1)
    return wsvg(cloud+'<g '+s+'><line x1="8.5" y1="18" x2="7.5" y2="21"/><line x1="12" y1="18" x2="11" y2="21"/><line x1="15.5" y1="18" x2="14.5" y2="21"/></g>');
  if(name.indexOf("snow")>-1)
    return wsvg(cloud+'<g '+s+'><line x1="8.5" y1="19" x2="8.5" y2="19"/><line x1="12" y1="20" x2="12" y2="20"/><line x1="15.5" y1="19" x2="15.5" y2="19"/></g>');
  if(name.indexOf("fog")>-1||name.indexOf("mist")>-1||name.indexOf("haze")>-1)
    return wsvg('<g '+s+'><line x1="4" y1="9" x2="20" y2="9"/><line x1="4" y1="13" x2="20" y2="13"/><line x1="4" y1="17" x2="20" y2="17"/></g>');
  if(name.indexOf("clear")>-1 && name.indexOf("night")>-1)
    return wsvg('<path '+s+' d="M18 14.5A6 6 0 1 1 10.5 6 4.8 4.8 0 0 0 18 14.5z"/>');
  if(name.indexOf("clear")>-1||name.indexOf("sunny")>-1||(name.indexOf("sun")>-1&&name.indexOf("cloud")<0))
    return wsvg('<circle cx="12" cy="12" r="4.2" '+s+'/><g '+s+'><line x1="12" y1="2.5" x2="12" y2="5"/><line x1="12" y1="19" x2="12" y2="21.5"/><line x1="2.5" y1="12" x2="5" y2="12"/><line x1="19" y1="12" x2="21.5" y2="12"/><line x1="5.2" y1="5.2" x2="7" y2="7"/><line x1="17" y1="17" x2="18.8" y2="18.8"/><line x1="18.8" y1="5.2" x2="17" y2="7"/><line x1="7" y1="17" x2="5.2" y2="18.8"/></g>');
  if(name.indexOf("partly")>-1||name.indexOf("part")>-1)
    return wsvg('<g '+s+'><circle cx="8.5" cy="8" r="3"/><line x1="8.5" y1="2.6" x2="8.5" y2="3.8"/><line x1="3.1" y1="8" x2="4.3" y2="8"/><line x1="4.7" y1="4.2" x2="5.5" y2="5"/><line x1="12.3" y1="4.2" x2="11.5" y2="5"/></g><path '+s+' d="M7 18h9a3 3 0 0 0 .2-6A4.4 4.4 0 0 0 8 11 3.1 3.1 0 0 0 7 18z"/>');
  return wsvg(cloud);
}

function dataMap(){
  var rows=(appsmith.model&&appsmith.model.rows)||[];
  var map={}, maxKey="";
  rows.forEach(function(r){ var k=String(r.date||"").slice(0,10); if(k){ map[k]=r; if(k>maxKey) maxKey=k; } });
  return { map:map, maxKey:maxKey };
}

function ensureInit(dm){
  if(inited) return;
  inited=true;
  var base = dm.maxKey ? dm.maxKey : null;
  var d = base ? new Date(Number(base.slice(0,4)), Number(base.slice(5,7))-1, 1) : new Date();
  selY=d.getFullYear(); selM=d.getMonth(); pickerYear=selY;
}

function fmt2(x){ return x<10?("0"+x):(""+x); }
function keyOf(dt){ return dt.getFullYear()+"-"+fmt2(dt.getMonth()+1)+"-"+fmt2(dt.getDate()); }

function pickerHtml(){
  if(!pickerOpen) return '';
  var cells=MONTHS.map(function(name,i){ var on=(selY===pickerYear && selM===i); return '<b class="'+(on?"on":"")+'" data-m="'+i+'">'+M3[i]+'</b>'; }).join('');
  return '<div class="pop" id="pop"><div class="nav"><span data-nav="-1">‹</span><b>'+pickerYear+'</b><span data-nav="1">›</span></div><div class="grid">'+cells+'</div></div>';
}

function render(){
  var m=appsmith.model||{};
  var dm=dataMap();
  ensureInit(dm);

  // monthly totals (selected month only)
  var hddT=0, cddT=0, di=new Date(selY, selM, 1);
  while(di.getMonth()===selM){ var r=dm.map[keyOf(di)]; if(r){ hddT+=Number(r.hdd||0); cddT+=Number(r.cdd||0); } di.setDate(di.getDate()+1); }

  var dateLabel=MONTHS[selM]+" "+selY;
  var top='<div class="top">'
    +'<div class="fld" style="position:relative"><label>Go to Month</label>'
      +'<div class="dateinput'+((selY!=null)?' has':'')+'" id="dateInput">'+CAL+'<span class="ph">'+esc(dateLabel)+'</span></div>'
      +pickerHtml()
    +'</div>'
    +'<div class="monthnav"><span class="arw" id="prev">‹</span><div class="lbl"><div class="m">'+esc(MONTHS[selM])+'</div><div class="y">'+selY+'</div></div><span class="arw" id="next">›</span></div>'
    +'<div class="totals">Monthly HDD:<b>'+n2(hddT)+'</b><br>Monthly CDD:<b>'+n2(cddT)+'</b></div>'
  +'</div>';

  var body;
  if(m.isLoading){ body='<div class="empty">Loading…</div>'; }
  else {
    // grid: last day of previous month (spillover) + every day of selected month
    var first=new Date(selY, selM, 1);
    var start=new Date(selY, selM, 1); start.setDate(0); // last day of prev month
    var end=new Date(selY, selM+1, 0);                   // last day of this month
    var cards='';
    var cur=new Date(start.getTime());
    while(cur<=end){
      var k=keyOf(cur);
      var out=(cur.getMonth()!==selM);
      var r=dm.map[k];
      var hdName=DOW[cur.getDay()]+' - '+fmt2(cur.getDate());
      var head='<div class="hd">'+(r?icon(r.icon):icon(""))+'<span>'+esc(hdName)+'</span></div>';
      var bd;
      if(r){
        bd='<div class="bd">'
          +'<div class="r"><span class="k">Min Temp (F)</span><span class="v">'+n2(r.minTemp)+'</span></div>'
          +'<div class="r"><span class="k">Max Temp (F)</span><span class="v">'+n2(r.maxTemp)+'</span></div>'
          +'<div class="r"><span class="k">HDD</span><span class="v">'+n2(r.hdd)+'</span></div>'
          +'<div class="r"><span class="k">CDD</span><span class="v">'+n2(r.cdd)+'</span></div>'
          +'</div>';
        cards+='<div class="card'+(out?' out':'')+'">'+head+bd+'</div>';
      } else {
        bd='<div class="bd"><div class="msg">No Data for this Period</div></div>';
        cards+='<div class="card nodata'+(out?' out':'')+'">'+head+bd+'</div>';
      }
      cur.setDate(cur.getDate()+1);
    }
    body='<div class="cal">'+cards+'</div>';
  }

  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+top+body+'</div>';
  bind();
}

function stepMonth(delta){
  var d=new Date(selY, selM+delta, 1);
  selY=d.getFullYear(); selM=d.getMonth(); pickerYear=selY;
}

function bind(){
  var prev=document.getElementById("prev"); if(prev) prev.onclick=function(){ stepMonth(-1); render(); };
  var next=document.getElementById("next"); if(next) next.onclick=function(){ stepMonth(1); render(); };
  var di=document.getElementById("dateInput"); if(di) di.onclick=function(){ pickerOpen=!pickerOpen; render(); };
  var pop=document.getElementById("pop");
  if(pop){
    var navs=pop.querySelectorAll("[data-nav]");
    for(var i=0;i<navs.length;i++){ (function(s){ s.onclick=function(){ pickerYear+=parseInt(s.getAttribute("data-nav"),10); render(); }; })(navs[i]); }
    var mbs=pop.querySelectorAll("[data-m]");
    for(var j=0;j<mbs.length;j++){ (function(b){ b.onclick=function(){ selM=parseInt(b.getAttribute("data-m"),10); selY=pickerYear; pickerOpen=false; render(); }; })(mbs[j]); }
  }
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

