  while(di.getMonth()===selM){ var r=dm.map[keyOf(di)]; if(r){ hddT+=Number(r.hdd||0); cddT+=Number(r.cdd||0); } di.setDate(di.getDate()+1); }

  var dateLabel=MONTHS[selM]+" "+selY;
  var top='<div class="top">'
    +'<div class="fld" style="position:relative"><label>Go to Month</label>'
      +'<div class="dateinput'+((selY!=null)?' has':'')+'" id="dateInput">'+CAL+'<span class="ph">'+esc(dateLabel)+'</span></div>'
      +pickerHtml()
    +'</div>'
    +'<div class="monthnav"><span class="arw" id="prev">‹</span><div class="lbl"><div class="m">'+esc(MONTHS[selM])+'</div><div class="y">'+selY+'</div></div><span class="arw" id="next">›</span></div>'
    +'<div class="totals">Monthly HDD:<b>'+n2(hddT)+'</b><br>Monthly CDD:<b>'+n2(cddT)+'</b></div>'
  +'</div>';

  var body;
  if(m.isLoading){ body='<div class="empty">Loading…</div>'; }
  else {
    // grid: last day of previous month (spillover) + every day of selected month
    var first=new Date(selY, selM, 1);
    var start=new Date(selY, selM, 1); start.setDate(0); // last day of prev month
    var end=new Date(selY, selM+1, 0);                   // last day of this month
    var cards='';
    var cur=new Date(start.getTime());
    while(cur<=end){
      var k=keyOf(cur);
      var out=(cur.getMonth()!==selM);
      var r=dm.map[k];
      var hdName=DOW[cur.getDay()]+' - '+fmt2(cur.getDate());
      var head='<div class="hd">'+(r?icon(r.icon):icon(""))+'<span>'+esc(hdName)+'</span></div>';
      var bd;
      if(r){
        bd='<div class="bd">'
          +'<div class="r"><span class="k">Min Temp (F)</span><span class="v">'+n2(r.minTemp)+'</span></div>'
          +'<div class="r"><span class="k">Max Temp (F)</span><span class="v">'+n2(r.maxTemp)+'</span></div>'
          +'<div class="r"><span class="k">HDD</span><span class="v">'+n2(r.hdd)+'</span></div>'
          +'<div class="r"><span class="k">CDD</span><span class="v">'+n2(r.cdd)+'</span></div>'
          +'</div>';
        cards+='<div class="card'+(out?' out':'')+'">'+head+bd+'</div>';
      } else {
        bd='<div class="bd"><div class="msg">No Data for this Period</div></div>';
        cards+='<div class="card nodata'+(out?' out':'')+'">'+head+bd+'</div>';
      }
      cur.setDate(cur.getDate()+1);
    }
    body='<div class="cal">'+cards+'</div>';
  }

  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+top+body+'</div>';
  bind();
}

function stepMonth(delta){
  var d=new Date(selY, selM+delta, 1);
  selY=d.getFullYear(); selM=d.getMonth(); pickerYear=selY;
}

function bind(){
  var prev=document.getElementById("prev"); if(prev) prev.onclick=function(){ stepMonth(-1); render(); };
  var next=document.getElementById("next"); if(next) next.onclick=function(){ stepMonth(1); render(); };
  var di=document.getElementById("dateInput"); if(di) di.onclick=function(){ pickerOpen=!pickerOpen; render(); };
  var pop=document.getElementById("pop");
  if(pop){
    var navs=pop.querySelectorAll("[data-nav]");
    for(var i=0;i<navs.length;i++){ (function(s){ s.onclick=function(){ pickerYear+=parseInt(s.getAttribute("data-nav"),10); render(); }; })(navs[i]); }
    var mbs=pop.querySelectorAll("[data-m]");
    for(var j=0;j<mbs.length;j++){ (function(b){ b.onclick=function(){ selM=parseInt(b.getAttribute("data-m"),10); selY=pickerYear; pickerOpen=false; render(); }; })(mbs[j]); }
  }
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });
